+export interface Page<T> {
+  items: T[];
+  page: number;
+  pageSize: number;
+  total: number;
+}
+
+/**
+ * Slice one page out of a full result set. `page` is 1-based.
+ */
+export function paginate<T>(all: T[], page: number, pageSize: number): Page<T> {
+  const start = (page - 1) * pageSize;
+  const end = start + pageSize - 1;
+  return { items: all.slice(start, end), page, pageSize, total: all.length };
+}
